--
-- Name: get_monthly_inventory_movement(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_monthly_inventory_movement(months_back integer DEFAULT 6) RETURNS TABLE(month date, received_qty bigint, released_qty bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    date_trunc('month', created_at)::date AS month,
    COALESCE(SUM(quantity_change) FILTER (WHERE action_type IN ('Received', 'Replenish') AND quantity_change > 0), 0) AS received_qty,
    COALESCE(SUM(ABS(quantity_change)) FILTER (WHERE action_type IN ('Released', 'Release')), 0) AS released_qty
  FROM inventory_logs
  WHERE created_at >= date_trunc('month', now()) - (months_back - 1) * INTERVAL '1 month'
  GROUP BY date_trunc('month', created_at)
  ORDER BY month;
$$;


ALTER FUNCTION public.get_monthly_inventory_movement(months_back integer) OWNER TO postgres;

--
-- Name: get_top_used_medicines(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_top_used_medicines(days_back integer DEFAULT 30, result_limit integer DEFAULT 5) RETURNS TABLE(medicine_id integer, medicine_name character varying, total_released bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT
    m.medicine_id,
    m.medicine_name,
    SUM(ABS(l.quantity_change)) AS total_released
  FROM inventory_logs l
  JOIN medicines m ON m.medicine_id = l.medicine_id
  WHERE l.action_type IN ('Released', 'Release')
    AND l.medicine_id IS NOT NULL
    AND l.created_at >= now() - (days_back || ' days')::INTERVAL
  GROUP BY m.medicine_id, m.medicine_name
  ORDER BY total_released DESC
  LIMIT result_limit;
$$;


ALTER FUNCTION public.get_top_used_medicines(days_back integer, result_limit integer) OWNER TO postgres;

