--
-- Name: link_current_auth_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.link_current_auth_user() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id INTEGER;
BEGIN
  IF auth.uid() IS NULL OR auth.email() IS NULL THEN
    RETURN NULL;
  END IF;

  UPDATE users
  SET auth_user_id = auth.uid()
  WHERE lower(email) = lower(auth.email())
    AND (auth_user_id IS NULL OR auth_user_id <> auth.uid())
  RETURNING user_id INTO v_user_id;

  IF v_user_id IS NULL THEN
    SELECT user_id INTO v_user_id FROM users WHERE lower(email) = lower(auth.email());
  END IF;

  RETURN v_user_id;
END;
$$;


ALTER FUNCTION public.link_current_auth_user() OWNER TO postgres;

