CREATE FUNCTION public.prevent_duplicate_active_emergency() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.subject_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM emergency_alerts
    WHERE subject_id = NEW.subject_id
      AND status <> 'Resolved'
  ) THEN
    RAISE EXCEPTION 'A new alert cannot be created while there is an unresolved alert. Please contact the clinic staff to resolve the existing alert before creating a new one.';
  END IF;
  RETURN NEW;
END;
$$;


