--

CREATE FUNCTION public.record_failed_login(p_email text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_attempts INTEGER;
BEGIN
  UPDATE users
  SET failed_login_attempts = failed_login_attempts + 1
  WHERE upper(email) = upper(p_email) AND is_active = true
  RETURNING failed_login_attempts INTO v_attempts;

  IF v_attempts >= 15 THEN
    UPDATE users SET is_active = false WHERE upper(email) = upper(p_email);
  END IF;
END;
$$;


ALTER FUNCTION public.record_failed_login(p_email text) OWNER TO postgres;

