--
-- Name: equipment_inventory_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.equipment_inventory_view WITH (security_invoker='on') AS
 SELECT equipment_id,
    equipment_name AS name,
    'Equipment'::character varying(20) AS category,
    COALESCE(( SELECT sum(b.quantity) AS sum
           FROM public.equipment_batches b
          WHERE ((b.equipment_id = eq.equipment_id) AND ((b.status)::text = 'Active'::text))), (0)::bigint) AS quantity,
    unit,
    min_stock,
    ( SELECT min(b.expiration_date) AS min
           FROM public.equipment_batches b
          WHERE ((b.equipment_id = eq.equipment_id) AND ((b.status)::text = 'Active'::text) AND (b.expiration_date IS NOT NULL))) AS expiration_date,
    ( SELECT b.received_date
           FROM public.equipment_batches b
          WHERE (b.equipment_id = eq.equipment_id)
          ORDER BY b.created_at DESC, b.equipment_batch_id DESC
         LIMIT 1) AS received_date,
    ( SELECT b.batch_number
           FROM public.equipment_batches b
          WHERE (b.equipment_id = eq.equipment_id)
          ORDER BY b.created_at DESC, b.equipment_batch_id DESC
         LIMIT 1) AS batch_no,
    ( SELECT b.purchase_reference
           FROM public.equipment_batches b
          WHERE (b.equipment_id = eq.equipment_id)
          ORDER BY b.created_at DESC, b.equipment_batch_id DESC
         LIMIT 1) AS purchase_reference,
    ( SELECT s.supplier_name
           FROM (public.equipment_batches b
             LEFT JOIN public.suppliers s ON ((s.supplier_id = b.supplier_id)))
          WHERE (b.equipment_id = eq.equipment_id)
          ORDER BY b.created_at DESC, b.equipment_batch_id DESC
         LIMIT 1) AS supplier,
    ( SELECT count(*) AS count
           FROM public.equipment_batches b
          WHERE (b.equipment_id = eq.equipment_id)) AS batch_count,
    false AS is_fifo,
    COALESCE(( SELECT bool_or((b.needs_maintenance OR ((b.expiration_date IS NOT NULL) AND (b.expiration_date < CURRENT_DATE)))) AS bool_or
           FROM public.equipment_batches b
          WHERE ((b.equipment_id = eq.equipment_id) AND ((b.status)::text = 'Active'::text))), false) AS needs_maintenance,
    description,
    image_url,
    active,
    created_at,
    updated_at
   FROM public.equipment eq
  WHERE (active = true);


ALTER VIEW public.equipment_inventory_view OWNER TO postgres;

