--
-- Name: medicine_inventory_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.medicine_inventory_view WITH (security_invoker='on') AS
 SELECT medicine_id,
    medicine_name AS name,
    'Medicine'::character varying(20) AS category,
    COALESCE(( SELECT sum(mb.quantity) AS sum
           FROM public.medicine_batches mb
          WHERE ((mb.medicine_id = m.medicine_id) AND ((mb.status)::text = 'Active'::text))), (0)::bigint) AS quantity,
    unit,
    min_stock,
    ( SELECT min(mb.expiration_date) AS min
           FROM public.medicine_batches mb
          WHERE ((mb.medicine_id = m.medicine_id) AND ((mb.status)::text = 'Active'::text) AND (mb.expiration_date IS NOT NULL))) AS expiration_date,
    ( SELECT mb.received_date
           FROM public.medicine_batches mb
          WHERE (mb.medicine_id = m.medicine_id)
          ORDER BY mb.created_at DESC, mb.medicine_batch_id DESC
         LIMIT 1) AS received_date,
    ( SELECT mb.batch_number
           FROM public.medicine_batches mb
          WHERE (mb.medicine_id = m.medicine_id)
          ORDER BY mb.created_at DESC, mb.medicine_batch_id DESC
         LIMIT 1) AS batch_no,
    ( SELECT mb.purchase_reference
           FROM public.medicine_batches mb
          WHERE (mb.medicine_id = m.medicine_id)
          ORDER BY mb.created_at DESC, mb.medicine_batch_id DESC
         LIMIT 1) AS purchase_reference,
    ( SELECT s.supplier_name
           FROM (public.medicine_batches mb
             LEFT JOIN public.suppliers s ON ((s.supplier_id = mb.supplier_id)))
          WHERE (mb.medicine_id = m.medicine_id)
          ORDER BY mb.created_at DESC, mb.medicine_batch_id DESC
         LIMIT 1) AS supplier,
    ( SELECT count(*) AS count
           FROM public.medicine_batches mb
          WHERE (mb.medicine_id = m.medicine_id)) AS batch_count,
    ( SELECT mb.status
           FROM public.medicine_batches mb
          WHERE (mb.medicine_id = m.medicine_id)
          ORDER BY mb.created_at DESC, mb.medicine_batch_id DESC
         LIMIT 1) AS latest_batch_status,
    true AS is_fifo,
    false AS needs_maintenance,
    generic_name,
    brand_name,
    dosage,
    strength,
    form,
    storage_requirement,
    description,
    image_url,
    active,
    created_at,
    updated_at
   FROM public.medicines m
  WHERE (active = true);


