--
-- Name: supply_inventory_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.supply_inventory_view WITH (security_invoker='on') AS
 SELECT supply_id,
    supply_name AS name,
    'Supply'::character varying(20) AS category,
    COALESCE(( SELECT sum(b.quantity) AS sum
           FROM public.supply_batches b
          WHERE ((b.supply_id = sp.supply_id) AND ((b.status)::text = 'Active'::text))), (0)::bigint) AS quantity,
    unit,
    min_stock,
    ( SELECT min(b.expiration_date) AS min
           FROM public.supply_batches b
          WHERE ((b.supply_id = sp.supply_id) AND ((b.status)::text = 'Active'::text) AND (b.expiration_date IS NOT NULL))) AS expiration_date,
    ( SELECT b.received_date
           FROM public.supply_batches b
          WHERE (b.supply_id = sp.supply_id)
          ORDER BY b.created_at DESC, b.supply_batch_id DESC
         LIMIT 1) AS received_date,
    ( SELECT b.batch_number
           FROM public.supply_batches b
          WHERE (b.supply_id = sp.supply_id)
          ORDER BY b.created_at DESC, b.supply_batch_id DESC
         LIMIT 1) AS batch_no,
    ( SELECT b.purchase_reference
           FROM public.supply_batches b
          WHERE (b.supply_id = sp.supply_id)
          ORDER BY b.created_at DESC, b.supply_batch_id DESC
         LIMIT 1) AS purchase_reference,
    ( SELECT s.supplier_name
           FROM (public.supply_batches b
             LEFT JOIN public.suppliers s ON ((s.supplier_id = b.supplier_id)))
          WHERE (b.supply_id = sp.supply_id)
          ORDER BY b.created_at DESC, b.supply_batch_id DESC
         LIMIT 1) AS supplier,
    ( SELECT count(*) AS count
           FROM public.supply_batches b
          WHERE (b.supply_id = sp.supply_id)) AS batch_count,
    false AS is_fifo,
    false AS needs_maintenance,
    description,
    image_url,
    active,
    created_at,
    updated_at
   FROM public.supplies sp
  WHERE (active = true);


ALTER VIEW public.supply_inventory_view OWNER TO postgres;

